{
  "units": [
    {
      "quote_ref": "F000",
      "scope_refs": [],
      "kind": "background",
      "meaning": "29 CFR 825.110 provides the title and subject heading defining and establishing the rules for an eligible employee under the Family and Medical Leave Act."
    },
    {
      "quote_ref": "F001:F004",
      "scope_refs": [],
      "kind": "definition",
      "meaning": "An eligible employee is defined as an employee of a covered employer who has been employed by the employer for at least 12 months, has been employed for at least 1,250 hours of service during the 12-month period immediately preceding the commencement of the leave (subject to special requirements for airline flight crew employees under 29 CFR 825.801), and is employed at a worksite where 50 or more employees are employed by the employer within 75 miles of that worksite."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F001:F002"],
      "kind": "exemption",
      "meaning": "The 12 months an employee must have been employed by the employer need not be consecutive months, provided the qualifying conditions regarding breaks in service are met."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F005"],
      "kind": "exemption",
      "meaning": "Subject to the specified exceptions for USERRA service or written rehire agreements, employment periods prior to a break in service of seven years or more need not be counted in determining whether the employee has been employed by the employer for at least 12 months."
    },
    {
      "quote_ref": "F007:F008",
      "scope_refs": ["F005"],
      "kind": "exception",
      "meaning": "Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where the employee's break in service is occasioned by the fulfillment of their USERRA-covered service obligation, and the period of absence from work due to or necessitated by USERRA-covered service must also be counted toward the 12-month requirement, provided that this section does not confer any greater entitlement than is available under USERRA."
    },
    {
      "quote_ref": "F007:F009",
      "scope_refs": ["F005"],
      "kind": "exception",
      "meaning": "Employment periods preceding a break in service of more than seven years must be counted in determining whether the employee has been employed by the employer for at least 12 months where a written agreement, including a collective bargaining agreement, exists concerning the employer's intention to rehire the employee after the break in service (such as for education or childrearing purposes)."
    },
    {
      "quote_ref": "F010",
      "scope_refs": ["F001:F002", "F005"],
      "kind": "definition",
      "meaning": "If an employee is maintained on the payroll for any part of a week, including any periods of paid or unpaid leave (such as sick leave or vacation) during which other benefits or compensation are provided by the employer (e.g., workers' compensation or group health plan benefits), the week counts as a week of employment; and for intermittent, occasional, or casual employment, 52 weeks is deemed equal to 12 months."
    },
    {
      "quote_ref": "F011",
      "scope_refs": ["F005"],
      "kind": "permission",
      "meaning": "Employers are permitted to consider employment prior to a continuous break in service of more than seven years when determining whether an employee has met the 12-month employment requirement."
    },
    {
      "quote_ref": "F011",
      "scope_refs": ["F005"],
      "kind": "requirement",
      "meaning": "If an employer chooses to recognize prior employment preceding a continuous break in service of more than seven years, the employer must do so uniformly with respect to all employees with similar breaks in service."
    },
    {
      "quote_ref": "F012",
      "scope_refs": ["F001", "F003"],
      "kind": "requirement",
      "meaning": "Except as provided for USERRA-covered service and in 29 CFR 825.801 for airline flight crew employees, whether an employee has worked the minimum 1,250 hours of service is determined according to the Fair Labor Standards Act (FLSA) principles for compensable hours of work, based on the actual number of hours worked; this determination is not limited by methods of recordkeeping or non-reflective compensation agreements, and any accurate accounting of actual hours worked under FLSA principles may be used."
    },
    {
      "quote_ref": "F013",
      "scope_refs": ["F001", "F003"],
      "kind": "requirement",
      "meaning": "An employee reemployed following USERRA-covered service must be credited with the hours of service that would have been worked for the employer during the period of absence due to or necessitated by that service, which are added to hours actually worked during the previous 12-month period to satisfy the 1,250 hours of service requirement; the employee's pre-service work schedule can generally be used to determine those hours, subject to special rules for airline flight crew employees under 29 CFR 825.801(c)."
    },
    {
      "quote_ref": "F014",
      "scope_refs": ["F001", "F003"],
      "kind": "requirement",
      "meaning": "If an employer fails to maintain an accurate record of hours worked by an employee—including employees exempt from FLSA recordkeeping requirements—the employer bears the burden of showing that the employee did not work the requisite 1,250 hours, and must be able to clearly demonstrate this fact (for example, by showing that full-time teachers did not work 1,250 hours during the previous 12 months) in order to claim the employee is ineligible for FMLA leave, subject to special rules for airline flight crew under 29 CFR 825.801(d)."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F001:F003"],
      "kind": "requirement",
      "meaning": "The determination of whether an employee meets the hours of service requirement and the 12-month employment requirement must be made as of the date the FMLA leave is scheduled to start."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F001:F003"],
      "kind": "statement",
      "meaning": "An employee may be on non-FMLA leave when they satisfy the 12-month eligibility requirement, and if so, any portion of the leave taken for an FMLA-qualifying reason after meeting the requirement constitutes FMLA leave."
    },
    {
      "quote_ref": "F016",
      "scope_refs": ["F001", "F004"],
      "kind": "requirement",
      "meaning": "Whether 50 employees are employed within 75 miles of the employee's worksite must be determined as of the date the employee gives notice of the need for leave."
    },
    {
      "quote_ref": "F016",
      "scope_refs": ["F001", "F004"],
      "kind": "statement",
      "meaning": "Regardless of whether leave is taken at one time or on an intermittent or reduced leave schedule basis, once an employee is determined eligible based on their notice of the need for leave, their eligibility is not affected by any subsequent change in the employee headcount at or within 75 miles of the worksite for that specific notice."
    },
    {
      "quote_ref": "F016",
      "scope_refs": ["F001", "F004"],
      "kind": "prohibition",
      "meaning": "An employer is prohibited from terminating an employee's leave that has already commenced if the employee headcount drops below 50."
    }
  ]
}
